class RecoveryAttemptFailedError(Exception):
    """ Raised when given recovery method doesn't end with success"""
    pass


class IterationFailedError(Exception):
    """ Raised when given sw differs from active one"""
    pass


class TestPreconditionFailed(Exception):
    """ Raised when checking nodes failed in test precondition"""
    pass


class TestFailedOnTeardownError(Exception):
    """ Raised when given sw differs from active one"""
    pass


class TestExecutionFailed(Exception):
    """ Raised when not all test results are passed"""
    pass


class MissingDeltaPlanError(Exception):
    """ Raised when delta was not provided and creating new delta failed"""
    pass


class RestoreBaseScfError(Exception):
    """ Raised when restoring base scf failed"""
    pass


class RecoveryAborted(Exception):
    """ Raised when Recovery is aborted due to stop_test_after_fail=True or critical alarms detected"""
    pass


class CommonTestSetupError(Exception):
    """ Raised when test nodes are not setup correctly"""
    pass


class IndependentSwUpdateError(Exception):
    """ Raised when independent sw update fail"""
    pass


class LiveUpdateNotPerformed(Exception):
    """ Raised when small update is not performed"""
    pass


class SoftwarePrecheckError(Exception):
    """ Raised when software precheck fail"""
    pass


class IntegrationFailedError(Exception):
    """ Raised when inegration with Netact fail"""
    pass
